import json
from cpmpy import *
import numpy as np

X = -1
game_data = [  # 0-8: number of mines around, -1: not opened
    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

rows = len(game_data)
cols = len(game_data[0])

# Create a variable grid for mines: 1 if mine, 0 if safe
mines = intvar(0, 1, shape=(rows, cols))

model = Model()

# For cells that are opened (0-8), the sum of mines in adjacent cells must equal the number
for r in range(rows):
    for c in range(cols):
        if game_data[r][c] != X:
            # Collect neighbors coordinates
            neighbors = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if not (nr == r and nc == c):
                            neighbors.append(mines[nr, nc])
            # The sum of mines around must be equal to the clue
            model += (sum(neighbors) == game_data[r][c])
        else:
            # For unopened cells, no direct clue, but they can be mine or not
            pass

# Additionally, cells that are opened cannot be mines themselves
for r in range(rows):
    for c in range(cols):
        if game_data[r][c] != X:
            model += (mines[r, c] == 0)

if model.solve():
    # Extract solution as a list of lists of 0/1
    mines_solution = mines.value().tolist()
    solution = {'mines': mines_solution}
    print(json.dumps(solution))
else:
    print("No solution found.")
